local parent = game:GetService("ReplicatedStorage"):WaitForChild("PanicShiftShared")
local s = parent:FindFirstChild("Types")
if not s or s.ClassName ~= "ModuleScript" then
    if s then s:Destroy() end
    s = Instance.new("ModuleScript")
    s.Name = "Types"
    s.Parent = parent
end
s.Source = "--!strict\n--[[\n    PANIC SHIFT: Types.lua\n    Exported Luau types for strict compile-time checking across services,\n    controllers, networks, and data stores.\n]]\n\nexport type RoundState = \"LOBBY\" | \"PREPARATION\" | \"ACTIVE\" | \"CLOSING\" | \"RESULTS\" | \"RESET\"\n\nexport type TaskType = \"RESTOCK\" | \"CLEAN_SPILL\" | \"DELIVER_ORDER\" | \"REPAIR\"\n\nexport type TaskData = {\n    Id: string,\n    Type: TaskType,\n    Title: string,\n    LocationPart: BasePart?,\n    Position: Vector3,\n    IsActive: boolean,\n    IsCompleted: boolean,\n    AssignedPlayer: Player?,\n    CreatedAt: number,\n    ExpiresAt: number?,\n    Metadata: { [string]: any }?,\n}\n\nexport type DisasterContext = {\n    RoundId: string,\n    Duration: number,\n    SupermarketMap: Model?,\n    Services: { [string]: any },\n    TelegraphDuration: number,\n}\n\nexport type LifetimeStats = {\n    shiftsCompleted: number,\n    shiftsWon: number,\n    tasksCompleted: number,\n    disastersSurvives: number,\n    spillsCleaned: number,\n    ordersDelivered: number,\n}\n\nexport type DailyChallengeProgress = {\n    resetKey: string,\n    completed: { [string]: boolean },\n    progress: { [string]: number },\n}\n\nexport type UserSettings = {\n    musicVolume: number,\n    sfxVolume: number,\n    screenShake: boolean,\n}\n\nexport type PlayerProfile = {\n    schemaVersion: number,\n    credits: number,\n    xp: number,\n    level: number,\n    ownedCosmetics: { string },\n    equippedCosmetic: string,\n    equippedHat: string?,\n    lifetimeStats: LifetimeStats,\n    dailyChallenges: DailyChallengeProgress,\n    settings: UserSettings,\n}\n\nexport type NetworkResponse = {\n    Success: boolean,\n    ErrorCode: string,\n    Message: string?,\n    Data: any?,\n}\n\nexport type RoundResultsData = {\n    Success: boolean,\n    ShiftName: string,\n    QuotaReached: number,\n    QuotaTarget: number,\n    DurationSeconds: number,\n    TeamBonusCredits: number,\n    IndividualStats: {\n        [number]: {\n            PlayerName: string,\n            TasksCompleted: number,\n            CreditsEarned: number,\n            XpEarned: number,\n            IsMvp: boolean,\n        }\n    },\n}\n\nexport type Service = {\n    Name: string,\n    Init: (self: any, services: { [string]: any }) -> (),\n    Start: (self: any) -> (),\n    [string]: any,\n}\n\nexport type Controller = {\n    Name: string,\n    Init: (self: any, controllers: { [string]: any }) -> (),\n    Start: (self: any) -> (),\n    [string]: any,\n}\n\nreturn {}\n"
return { success = true, name = "Types", bytes = #s.Source }
